1	/**
2	 * @module features/tv-dashboard/ui/TvDashboard.page
3	 *
4	 * Página `/tv` — Dashboard de Crise em TV 1920×1080 (design.md §1–§2, §7–§8).
5	 * Renderiza FORA do DashboardLayout (fullscreen, sem sidebar), em LIGHT
6	 * hardcoded (independe do toggle de tema): glassmorphism Momma sobre fundo
7	 * branco com ambiência da marca (awning, folhas, glows), zero scroll.
8	 */
9	
10	import { useEffect, useRef, useState } from 'react';
11	import { useNavigate } from 'react-router-dom';
12	import { Leaf, Settings2 } from 'lucide-react';
13	import { useTvDashboardData } from '../model/useTvDashboardData';
14	import { useTvRealtime } from '../model/useTvRealtime';
15	import { TvHero } from './TvHero';
16	import { TvStoreCard } from './TvStoreCard';
17	import { TvFabricaCard } from './TvFabricaCard';
18	import { TvExceptions } from './TvExceptions';
19	import { TvTopProducts } from './TvTopProducts';
20	import { useMinuteClock } from '../model/useMinuteClock';
21	import './tv.css';
22	
23	/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
24	const METAS_BUTTON_VISIBLE_MS = 5_000;
25	
26	/**
27	 * Ambiência Momma replicada do `MommaPageLayout` (que não cabe no chassi
28	 * fullscreen da TV): awning stripe verde no topo, folhas decorativas
29	 * ESTÁTICAS (sem `animate-pulse` — §8.2 proíbe animação contínua) e
30	 * ambient glows verde/dourado.
31	 */
32	function TvAmbience() {
33	  return (
34	    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden>
35	      {/* Awning stripe (toldo da marca) */}
36	      <div className="absolute left-0 right-0 top-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80" />
37	      {/* Folhas decorativas estáticas */}
38	      <div className="absolute right-[-10%] top-[-5%] h-[300px] w-[300px] opacity-[0.03]">
39	        <Leaf className="h-full w-full rotate-12 text-[#57715B]" />
40	      </div>
41	      <div className="absolute bottom-[-10%] left-[-15%] h-[400px] w-[400px] opacity-[0.03]">
42	        <Leaf className="h-full w-full -rotate-45 text-[#57715B]" />
43	      </div>
44	      {/* Ambient glows */}
45	      <div className="absolute left-[10%] top-[20%] h-[200px] w-[200px] rounded-full bg-[#57715B]/5 blur-[80px]" />
46	      <div className="absolute bottom-[30%] right-[10%] h-[250px] w-[250px] rounded-full bg-[#C5A065]/5 blur-[80px]" />
47	    </div>
48	  );
49	}
50	
51	/** Card-chassi anônimo do estado de erro total (design.md §7). */
52	function TvErrorCard() {
53	  return (
54	    <section className="relative flex flex-col overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150">
55	      <div
56	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
57	        aria-hidden
58	      />
59	      <div className="relative z-10 flex h-full flex-col">
60	        <div className="flex h-8 items-center justify-between">
61	          <span className="text-[28px] font-momma font-semibold text-[#7C887E]">—</span>
62	          <span className="inline-flex h-6 items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 text-[20px] font-momma font-medium text-amber-600">
63	            sem conexão
64	          </span>
65	        </div>
66	        <span className="mt-4 font-momma text-[64px] font-bold leading-none text-[#7C887E]">—</span>
67	      </div>
68	    </section>
69	  );
70	}
71	
72	/** Página raiz do painel TV. */
73	export default function TvDashboardPage() {
74	  const navigate = useNavigate();
75	  const data = useTvDashboardData();
76	  useTvRealtime();
77	  const now = useMinuteClock();
78	
79	  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
80	  // e suspende o cursor-none enquanto visível (design.md §8.4).
81	  const [controlsVisible, setControlsVisible] = useState(false);
82	  const hideTimer = useRef<number | null>(null);
83	  useEffect(() => {
84	    const onMove = () => {
85	      setControlsVisible(true);
86	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
87	      hideTimer.current = window.setTimeout(
88	        () => setControlsVisible(false),
89	        METAS_BUTTON_VISIBLE_MS,
90	      );
91	    };
92	    window.addEventListener('mousemove', onMove);
93	    return () => {
94	      window.removeEventListener('mousemove', onMove);
95	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
96	    };
97	  }, []);
98	
99	  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
100	  if (data.isLoading) {
101	    return (
102	      <div className="fixed inset-0 flex select-none flex-col items-center justify-center gap-5 overflow-hidden bg-white font-momma antialiased">
103	        <TvAmbience />
104	        <span className="relative text-[40px] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
105	          MOMMA
106	        </span>
107	        <span className="relative text-[24px] text-[#5F6F63]">carregando painel…</span>
108	        <div className="relative flex gap-2 text-[24px] text-[#7C887E]" aria-hidden>
109	          <span className="tv-dot">·</span>
110	          <span className="tv-dot">·</span>
111	          <span className="tv-dot">·</span>
112	        </div>
113	      </div>
114	    );
115	  }
116	
117	  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);
118	
119	  return (
120	    <div
121	      className={`fixed inset-0 select-none overflow-hidden bg-white font-momma text-[#2D362E] antialiased ${
122	        controlsVisible ? '' : 'cursor-none'
123	      }`}
124	      data-testid="tv-dashboard"
125	    >
126	      <TvAmbience />
127	
128	      <div className="tv-pixel-shift relative h-full">
129	        <div className="tv-content-enter grid h-full grid-rows-[152px_1fr_248px] gap-6 px-8 py-6">
130	          {/* Linha 1 — hero */}
131	          <TvHero network={data.network} freshness={data.freshness} now={now} />
132	
133	          {/* Linha 2 — grid 3×2 de unidades (fábrica na posição 6) */}
134	          <div className="grid grid-cols-3 grid-rows-2 gap-6">
135	            {data.isError ? (
136	              <>
137	                {Array.from({ length: 6 }, (_, i) => (
138	                  <TvErrorCard key={i} />
139	                ))}
140	              </>
141	            ) : (
142	              <>
143	                {storeCards.map((store) => (
144	                  <TvStoreCard
145	                    key={store.lojaId}
146	                    store={store}
147	                    liveLevel={data.freshness.vendasLive.level}
148	                    now={now}
149	                  />
150	                ))}
151	                {data.factory && (
152	                  <TvFabricaCard
153	                    factory={data.factory}
154	                    freshness={data.freshness}
155	                    now={now}
156	                  />
157	                )}
158	              </>
159	            )}
160	          </div>
161	
162	          {/* Linha 3 — exceções (2fr) + top 5 produtos (1fr) */}
163	          <div className="grid grid-cols-[2fr_1fr] gap-6">
164	            <TvExceptions exceptions={data.exceptions} />
165	            <TvTopProducts products={data.topProducts} />
166	          </div>
167	        </div>
168	      </div>
169	
170	      {/* Botão fantasma de Metas (§8.4) */}
171	      <button
172	        type="button"
173	        onClick={() => navigate('/tv/metas')}
174	        data-mia-action="abrir-metas-painel-tv"
175	        className={`fixed bottom-6 right-8 flex h-11 items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-5 text-[20px] font-momma font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none ${
176	          controlsVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
177	        }`}
178	        aria-hidden={!controlsVisible}
179	        tabIndex={controlsVisible ? 0 : -1}
180	      >
181	        <Settings2 style={{ width: 22, height: 22 }} aria-hidden />
182	        Metas
183	      </button>
184	    </div>
185	  );
186	}
