1	/**
2	 * @module features/tv-dashboard/ui/TvStoreCard
3	 *
4	 * Card de loja do Painel TV (602×280 — design.md §4): vendas do dia (ou
5	 * defasadas com selo honesto), barra de % meta, mini-stats e borda RAG
6	 * com redundância não-cromática (glow + chip de estado).
7	 * Chassi v2: glass premium (vidro branco + gradiente interno dourado sutil).
8	 */
9	
10	import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
11	import type { TvFreshnessLevel, TvStoreData } from '../model/types';
12	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
13	import {
14	  TvDeltaChip,
15	  TvMetaBar,
16	  TvSourceChip,
17	  TvStateChip,
18	  TvStockBadge,
19	} from './TvChips';
20	import {
21	  WEEKDAY_ABBR,
22	  expectedPctNow,
23	  formatInt,
24	  formatTicketBRL,
25	  formatTimeHHMM,
26	  formatWeekdayDayMonth,
27	  metaBarColorFromRatio,
28	} from './tvFormat';
29	import { useCountUp } from './useCountUp';
30	
31	interface TvStoreCardProps {
32	  store: TvStoreData;
33	  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
34	  liveLevel: TvFreshnessLevel;
35	  now: Date;
36	}
37	
38	/**
39	 * Borda + glow por estado RAG (design.md §4 — sinal lível a 5m).
40	 * Normal = vidro calmo; ÂMBAR/CRÍTICO ganham borda colorida + glow suave.
41	 */
42	const RAG_FRAME: Record<TvStoreData['rag'], string> = {
43	  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
44	  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
45	  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
46	};
47	
48	/** Card de loja: cobre canal Degust live e Linx defasado. */
49	export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
50	  const { vendas, metaDia, channel } = store;
51	  const isLive = channel === 'degust-live';
52	  const valorAnim = useCountUp(vendas?.valor ?? 0);
53	  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));
54	
55	  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
56	  const fullDayPct =
57	    vendas != null && metaDia != null && metaDia > 0
58	      ? (vendas.valor / metaDia) * 100
59	      : null;
60	  const expected = isLive ? expectedPctNow(now) : null;
61	  const barColor = isLive
62	    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
63	    : 'sage';
64	
65	  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
66	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
67	
68	  // Caption sob as vendas (design.md §4 item 4)
69	  let caption: string;
70	  if (vendas == null) {
71	    caption = 'sem dado de venda disponível';
72	  } else if (isLive) {
73	    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
74	    // dedicado pt-BR (new Date() falha para dia > 12).
75	    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
76	    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
77	  } else {
78	    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
79	  }
80	
81	  return (
82	    <section
83	      className={`relative overflow-hidden rounded-[2rem] bg-white/60 p-5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${RAG_FRAME[store.rag]}`}
84	      data-testid="tv-store-card"
85	      data-rag={store.rag}
86	    >
87	      {/* Gradiente interno sutil (assinatura glass premium) */}
88	      <div
89	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
90	        aria-hidden
91	      />
92	
93	      <div className="relative z-10 flex h-full flex-col">
94	        {/* Header: nome + chips */}
95	        <div className="flex h-8 items-center justify-between gap-3">
96	          <h2 className="truncate text-[28px] font-momma font-semibold leading-8 text-[#2D362E]">
97	            {store.nome}
98	          </h2>
99	          <div className="flex shrink-0 items-center gap-2">
100	            <TvStateChip rag={store.rag} />
101	            <TvStockBadge estoque={store.estoque} />
102	            <TvSourceChip
103	              channel={channel}
104	              liveLevel={liveLevel}
105	              laggedDate={vendas?.dataReferencia ?? null}
106	            />
107	          </div>
108	        </div>
109	
110	        {/* Vendas (64px) + delta */}
111	        <div className="mt-1.5 flex items-end gap-4">
112	          <span
113	            className={`font-momma text-[64px] font-bold leading-none tabular-nums ${vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
114	            data-testid="tv-store-sales"
115	          >
116	            {vendas ? formatCompactBRL(valorAnim) : '—'}
117	          </span>
118	          {store.deltaSemana != null && refDate != null && (
119	            <span className="pb-1">
120	              <TvDeltaChip
121	                delta={store.deltaSemana}
122	                weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
123	                size="card"
124	              />
125	            </span>
126	          )}
127	        </div>
128	        <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-[#7C887E]">
129	          {caption}
130	        </p>
131	
132	        {/* Barra de meta */}
133	        <div className="mt-2">
134	          <TvMetaBar
135	            fillPct={fullDayPct}
136	            expectedPct={fullDayPct != null ? expected : null}
137	            color={barColor}
138	            size="card"
139	          />
140	          <p className="mt-1.5 text-[22px] font-momma leading-tight">
141	            {fullDayPct != null ? (
142	              isLive ? (
143	                <>
144	                  <span className="font-medium text-[#5F6F63]">
145	                    {Math.round(fullDayPct)}% da meta
146	                  </span>
147	                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
148	                </>
149	              ) : (
150	                <span className="font-medium text-[#5F6F63]">
151	                  {Math.round(fullDayPct)}% da meta de{' '}
152	                  {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
153	                </span>
154	              )
155	            ) : (
156	              <span className="text-[#7C887E]">sem meta cadastrada</span>
157	            )}
158	          </p>
159	        </div>
160	
161	        {/* Mini-stats */}
162	        <div className="mt-auto grid grid-cols-3 gap-4">
163	          <div>
164	            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
165	              CUPONS
166	            </p>
167	            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
168	              {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
169	            </p>
170	          </div>
171	          <div>
172	            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
173	              TICKET
174	            </p>
175	            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
176	              {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
177	            </p>
178	          </div>
179	          <div>
180	            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
181	              FLUXO
182	            </p>
183	            <p className="mt-0.5 flex items-center gap-1 font-momma text-[28px] font-medium leading-none text-[#2D362E] tabular-nums">
184	              <ArrowUpRight style={{ width: 22, height: 22 }} className="text-[#5F6F63]" aria-hidden />
185	              {store.movimentacao.entradas}
186	              <ArrowDownRight
187	                style={{ width: 22, height: 22 }}
188	                className="ml-2 text-[#5F6F63]"
189	                aria-hidden
190	              />
191	              {store.movimentacao.saidas}
192	            </p>
193	          </div>
194	        </div>
195	      </div>
196	    </section>
197	  );
198	}
199

1	/**
2	 * @module features/tv-dashboard/ui/TvFabricaCard
3	 *
4	 * Card diferenciado da fábrica (602×280, posição 6 — design.md §5):
5	 * produção do dia (com data de referência explícita quando fallback),
6	 * expedições, última bipagem e hairline GOLD de assinatura.
7	 * Chassi v2: mesmo glass premium do TvStoreCard.
8	 */
9	
10	import { Factory } from 'lucide-react';
11	import type { TvFactoryData, TvFreshness } from '../model/types';
12	import {
13	  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
14	  TV_FACTORY_HOURS,
15	  parseIsoDateLocal,
16	  toIsoDateLocal,
17	} from '../model/tvMath';
18	import { TvSourceChip, TvStateChip, TvStockBadge } from './TvChips';
19	import {
20	  formatAgoLabel,
21	  formatInt,
22	  formatTimeHHMM,
23	  formatWeekdayDayMonth,
24	} from './tvFormat';
25	import { useCountUp } from './useCountUp';
26	
27	interface TvFabricaCardProps {
28	  factory: TvFactoryData;
29	  freshness: TvFreshness;
30	  now: Date;
31	}
32	
33	/** Borda + glow por estado RAG (mesmo chassi do TvStoreCard). */
34	const RAG_FRAME: Record<TvFactoryData['rag'], string> = {
35	  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
36	  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
37	  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
38	};
39	
40	/** Card da fábrica: nunca tem meta de venda — só produção/expedição/bip. */
41	export function TvFabricaCard({ factory, freshness, now }: TvFabricaCardProps) {
42	  const producao = factory.producao;
43	  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));
44	
45	  const todayIso = toIsoDateLocal(now);
46	  const isToday = producao?.dataReferencia === todayIso;
47	  const refLabel =
48	    producao && !isToday
49	      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
50	      : null;
51	  const updTime = formatTimeHHMM(freshness.estoque.updatedAt);
52	
53	  // Última bipagem: âmbar quando acima do threshold dentro da janela de
54	  // produção — MESMA janela/threshold do RAG da fábrica (TV_FACTORY_HOURS).
55	  const bip = factory.expedicoes.ultimaBipagem;
56	  const bipTime = formatTimeHHMM(bip);
57	  const bipAgo = formatAgoLabel(bip, now);
58	  const hour = now.getHours();
59	  const inProductionWindow =
60	    hour >= TV_FACTORY_HOURS.start && hour < TV_FACTORY_HOURS.end;
61	  const bipStale =
62	    inProductionWindow &&
63	    (bip == null ||
64	      now.getTime() - new Date(bip).getTime() >
65	        FACTORY_NO_MOVEMENT_THRESHOLD_HOURS * 3_600_000);
66	  const bipColor = bipStale ? 'text-amber-600' : 'text-[#2D362E]';
67	
68	  return (
69	    <section
70	      className={`relative overflow-hidden rounded-[2rem] bg-white/60 p-5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${RAG_FRAME[factory.rag]}`}
71	      data-testid="tv-fabrica-card"
72	      data-rag={factory.rag}
73	    >
74	      {/* Gradiente interno sutil (assinatura glass premium) */}
75	      <div
76	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
77	        aria-hidden
78	      />
79	      {/* Hairline gold de identidade (topo, sob o radius) */}
80	      <div className="absolute inset-x-0 top-0 h-0.5 bg-[#C5A065]/60" aria-hidden />
81	
82	      <div className="relative z-10 flex h-full flex-col">
83	        {/* Header */}
84	        <div className="flex h-8 items-center justify-between gap-3">
85	          <h2 className="flex items-center gap-2.5 truncate text-[28px] font-momma font-semibold leading-8 text-[#2D362E]">
86	            <Factory style={{ width: 26, height: 26 }} className="shrink-0 text-[#C5A065]" aria-hidden />
87	            {factory.nome}
88	          </h2>
89	          <div className="flex shrink-0 items-center gap-2">
90	            <TvStateChip rag={factory.rag} />
91	            <TvStockBadge estoque={factory.estoque} />
92	            <TvSourceChip channel="factory" liveLevel={freshness.estoque.level} />
93	          </div>
94	        </div>
95	
96	        {/* Produção (64px) */}
97	        <div className="mt-1.5 flex items-end gap-3">
98	          <span
99	            className={`font-momma text-[64px] font-bold leading-none tabular-nums ${producao ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
100	            data-testid="tv-fabrica-producao"
101	          >
102	            {producao ? formatInt(unidadesAnim) : '—'}
103	          </span>
104	          {producao && (
105	            <span className="pb-0.5 font-momma text-[32px] font-normal leading-none text-[#5F6F63]">
106	              un
107	            </span>
108	          )}
109	        </div>
110	        <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-[#7C887E]">
111	          {producao
112	            ? `produzido ${refLabel ? `em ${refLabel}` : 'hoje'}${updTime ? ` · atualizado ${updTime}` : ''}`
113	            : 'sem produção registrada'}
114	        </p>
