1	/**
2	 * @module features/tv-dashboard/ui/TvExceptions
3	 *
4	 * Faixa de exceções do Painel TV (1229×248 — design.md §6.1): grid 2×4
5	 * preenchido coluna-primeiro, máx 7 itens + slot de overflow "+N outros".
6	 * v2: linhas de vidro neutras — a COR vive só no ícone e no valor da
7	 * severidade; estado vazio explícito em emerald suave (nunca área em branco).
8	 */
9	
10	import { CheckCircle2, OctagonAlert, TriangleAlert } from 'lucide-react';
11	import type { TvException, TvExceptionsResult } from '../model/types';
12	
13	/**
14	 * Separa a linha em texto principal + valor à direita, por tipo de exceção
15	 * (design.md §6.1 — anatomia da linha).
16	 */
17	function splitException(ex: TvException): { text: string; value: string } {
18	  switch (ex.kind) {
19	    case 'stock-out':
20	      return {
21	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
22	        value: '0 un',
23	      };
24	    case 'stock-low':
25	      return {
26	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
27	        value: `${ex.quantidade ?? 0} · mín ${ex.quantidadeMinima ?? 0}`,
28	      };
29	    case 'no-movement': {
30	      const m = ex.message.match(/há \d+\s?h/);
31	      return {
32	        text: `${ex.lojaNome ?? 'Loja'} — sem bipagem`,
33	        value: m ? m[0] : '',
34	      };
35	    }
36	    case 'stale-data': {
37	      const m = ex.message.match(/desde \d{2}:\d{2}/);
38	      return {
39	        text: `${ex.lojaNome ?? 'Venda live'} — dado atrasado`,
40	        value: m ? m[0] : '',
41	      };
42	    }
43	  }
44	}
45	
46	/** Lista de exceções com estado vazio confirmado explicitamente. */
47	export function TvExceptions({ exceptions }: { exceptions: TvExceptionsResult }) {
48	  const { items, overflowCount, totalCount } = exceptions;
49	  const isEmpty = totalCount === 0;
50	
51	  return (
52	    <section
53	      className="relative h-full overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150"
54	      data-testid="tv-exceptions"
55	    >
56	      {/* Gradiente interno sutil (assinatura glass premium) */}
57	      <div
58	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
59	        aria-hidden
60	      />
61	
62	      <div className="relative z-10 flex h-full flex-col">
63	        <div className="flex h-7 items-center justify-between">
64	          <h2 className="text-[24px] font-momma font-semibold uppercase tracking-wider text-[#5F6F63]">
65	            EXCEÇÕES
66	          </h2>
67	          {totalCount > 0 && (
68	            <span className="font-momma text-[24px] font-medium leading-none text-[#7C887E] tabular-nums">
69	              {totalCount}
70	            </span>
71	          )}
72	        </div>
73	
74	        {isEmpty ? (
75	          <div
76	            className="flex h-full items-center justify-center gap-4"
77	            data-testid="tv-exceptions-empty"
78	          >
79	            <CheckCircle2 style={{ width: 44, height: 44 }} className="text-emerald-500" aria-hidden />
80	            <p className="text-[28px] font-momma font-medium text-emerald-600">
81	              Nenhum alerta — tudo dentro do normal
82	            </p>
83	          </div>
84	        ) : (
85	          <ul className="mt-3 grid flex-1 grid-flow-col grid-cols-2 grid-rows-4 gap-x-6 gap-y-2">
86	            {items.map((ex) => {
87	              const { text, value } = splitException(ex);
