89	              return (
90	                <li
91	                  key={ex.id}
92	                  className="tv-fade-in flex items-center gap-3 rounded-xl border border-[#57715B]/5 bg-white/50 px-3"
93	                  data-testid="tv-exception-row"
94	                  data-severity={ex.severity}
95	                >
96	                  {isRed ? (
97	                    <OctagonAlert
98	                      style={{ width: 24, height: 24 }}
99	                      className="shrink-0 text-red-500"
100	                      aria-hidden
101	                    />
102	                  ) : (
103	                    <TriangleAlert
104	                      style={{ width: 24, height: 24 }}
105	                      className="shrink-0 text-amber-500"
106	                      aria-hidden
107	                    />
108	                  )}
109	                  <span className="min-w-0 flex-1 truncate text-[24px] font-momma font-medium text-[#2D362E]">
110	                    {text}
111	                  </span>
112	                  {value && (
113	                    <span
114	                      className={`shrink-0 font-momma text-[24px] font-medium tabular-nums ${
115	                        isRed ? 'text-red-600' : 'text-amber-600'
116	                      }`}
117	                    >
118	                      {value}
119	                    </span>
120	                  )}
121	                </li>
122	              );
123	            })}
124	            {overflowCount > 0 && (
