1	/**
2	 * @module features/tv-dashboard/ui/TvChips
3	 *
4	 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
5	 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
6	 * badge de estoque e barra de % meta com tick de esperado.
7	 * Linguagem v2 (glassmorphism Momma): design.md §1.3–§1.6, §3 e §4.
8	 */
9	
10	import {
11	  ArrowDown,
12	  ArrowUp,
13	  CalendarClock,
14	  Check,
15	  OctagonAlert,
16	  RefreshCw,
17	  TriangleAlert,
18	} from 'lucide-react';
19	import type {
20	  TvFreshnessLevel,
21	  TvRagStatus,
22	  TvSalesChannel,
23	  TvStockAlertSummary,
24	} from '../model/types';
25	import { formatLaggedDateLabel } from '../model/tvMath';
26	import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	interface TvDeltaChipProps {
33	  /** Delta % vs mesmo dia da semana anterior. */
34	  delta: number;
35	  /** Abreviação do dia comparado ("qua."). */
36	  weekdayLabel: string;
37	  /** Tamanho: hero (28px) ou card de loja (24px). */
38	  size: 'hero' | 'card';
39	}
40	
41	/**
42	 * Chip de delta semanal. Neutro (pill sage suave) sempre — exceto delta
43	 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
44	 */
45	export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
46	  const isAlert = delta <= -15;
47	  const colorCls = isAlert
48	    ? 'bg-amber-50 text-amber-600'
49	    : 'bg-[#57715B]/8 text-[#5F6F63]';
50	  const textCls = size === 'hero' ? 'text-[28px]' : 'text-[24px]';
51	  const iconPx = size === 'hero' ? 28 : 24;
52	  const Icon = delta < 0 ? ArrowDown : ArrowUp;
53	  return (
54	    <span
55	      className={`inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 font-momma font-medium tabular-nums leading-none ${textCls} ${colorCls}`}
56	      data-testid="tv-delta-chip"
57	    >
58	      <Icon style={{ width: iconPx, height: iconPx }} aria-hidden />
59	      {formatDeltaPct(delta)} vs {weekdayLabel}
60	    </span>
61	  );
62	}
63	
64	// ─────────────────────────────────────────────────────────────────────────────
65	// Chip de fonte (freshness honesta — design.md §4 item 1)
66	// ─────────────────────────────────────────────────────────────────────────────
67	
68	interface TvSourceChipProps {
69	  channel: TvSalesChannel;
70	  /** Freshness da fonte live (ignorado para canal Linx). */
71	  liveLevel: TvFreshnessLevel;
72	  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
73	  laggedDate?: string | null;
74	}
75	
76	/**
77	 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
78	 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
79	 * (defasagem esperada não é alarme).
80	 */
81	export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
82	  if (channel === 'linx-lagged') {
83	    return (
84	      <span
85	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 text-[20px] font-momma font-medium leading-none text-[#5F6F63]"
86	        data-testid="tv-source-chip-lagged"
87	      >
88	        <CalendarClock style={{ width: 18, height: 18 }} aria-hidden />
89	        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
90	      </span>
91	    );
92	  }
93	  if (liveLevel === 'fresh') {
94	    return (
95	      <span
96	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-emerald-50 px-3 text-[20px] font-momma font-medium leading-none text-emerald-600"
97	        data-testid="tv-source-chip-live"
98	      >
