148	/**
149	 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
150	 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
151	 */
152	export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
153	  const total = estoque.zerados + estoque.abaixoMinimo;
