177	// ─────────────────────────────────────────────────────────────────────────────
178	// Barra de % meta com tick de "esperado agora"
179	// ─────────────────────────────────────────────────────────────────────────────
180	
181	const BAR_FILL_CLS: Record<TvBarColor, string> = {
182	  sage: 'bg-gradient-to-r from-[#57715B] to-[#4a6250]',
183	  amber: 'bg-gradient-to-r from-amber-400 to-amber-500',
184	  red: 'bg-gradient-to-r from-red-400 to-red-500',
185	};
186	
187	interface TvMetaBarProps {
188	  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
189	  fillPct: number | null;
190	  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
191	  expectedPct: number | null;
192	  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
193	  color: TvBarColor;
194	  /** Altura da barra: hero 20px, card 12px. */
195	  size: 'hero' | 'card';
196	}
197	
198	/**
199	 * Barra horizontal de % meta: trilha sage suave (`#57715B/10`),
200	 * preenchimento em gradiente por estado de venda e tick DOURADO de
201	 * "esperado agora" (pró-rata). Transição de width 600ms ease-out (§8.1.3).
202	 */
203	export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
204	  const heightCls = size === 'hero' ? 'h-5' : 'h-3';
205	  const tick =
206	    size === 'hero'
207	      ? { width: 3, height: 28, offset: -4 }
208	      : { width: 2, height: 20, offset: -4 };
209	  return (
210	    <div
211	      className={`relative w-full rounded-full bg-[#57715B]/10 ${heightCls}`}
212	      data-testid="tv-meta-bar"
213	    >
214	      {fillPct != null && (
215	        <div
216	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
217	          style={{ width: `${clampPct(fillPct)}%` }}
218	          data-testid="tv-meta-bar-fill"
219	        />
220	      )}
221	      {expectedPct != null && (
222	        <div
223	          className="absolute rounded-full bg-[#C5A065]"
224	          style={{
225	            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
226	            top: tick.offset,
227	            width: tick.width,
228	            height: tick.height,
229	          }}
230	          data-testid="tv-meta-bar-tick"
231	        />
232	      )}
233	    </div>
234	  );
235	}
