1	/*
2	 * Animações do Painel TV (/tv) — lista FECHADA do design.md §8.1 (v2).
3	 * Só transform/opacity (pixel-shift anti burn-in, fades, dots) — nenhuma
4	 * cor vive aqui. Importado apenas por TvDashboard.page.tsx; nada vaza
5	 * para o design system.
6	 */
7	
8	@media (prefers-reduced-motion: no-preference) {
9	  /* §8.1.5 — pixel-shift anti burn-in: ciclo de 16 min (960s), passos de
10	     1-2px com interpolação de ~2s (0.2% de 960s ≈ 1,9s) em cada troca. */
11	  @keyframes tv-pixel-shift {
12	    0% {
13	      transform: translate(0, 0);
14	    }
15	    24.8% {
16	      transform: translate(0, 0);
17	    }
18	    25% {
19	      transform: translate(1px, 1px);
20	    }
21	    49.8% {
22	      transform: translate(1px, 1px);
23	    }
24	    50% {
25	      transform: translate(0, 2px);
26	    }
27	    74.8% {
28	      transform: translate(0, 2px);
29	    }
30	    75% {
31	      transform: translate(-1px, 1px);
32	    }
33	    99.8% {
34	      transform: translate(-1px, 1px);
35	    }
36	    100% {
37	      transform: translate(0, 0);
38	    }
39	  }
40	
41	  .tv-pixel-shift {
42	    animation: tv-pixel-shift 960s ease-in-out infinite;
43	  }
44	
45	  /* §8.1.2 — fade-in de exceção nova (uma única vez) */
46	  @keyframes tv-fade-in {
47	    from {
48	      opacity: 0;
49	      transform: translateY(6px);
50	    }
51	    to {
52	      opacity: 1;
53	      transform: translateY(0);
54	    }
55	  }
56	
57	  .tv-fade-in {
58	    animation: tv-fade-in 300ms ease-out both;
59	  }
60	
61	  /* §7 — conteúdo entra com fade único de 300ms após o primeiro load */
62	  @keyframes tv-content-enter {
63	    from {
64	      opacity: 0;
65	    }
66	    to {
67	      opacity: 1;
68	    }
69	  }
70	
71	  .tv-content-enter {
72	    animation: tv-content-enter 300ms ease-out both;
73	  }
74	
75	  /* §7 — loading inicial: 3 pontos que acendem em sequência (1×/600ms),
76	     único movimento permitido fora do estado carregado. */
77	  @keyframes tv-dot {
78	    0%,
79	    100% {
80	      opacity: 0.2;
81	    }
82	    33% {
83	      opacity: 1;
84	    }
85	  }
86	
87	  .tv-dot {
88	    animation: tv-dot 1800ms steps(3, jump-none) infinite;
89	  }
90	
91	  .tv-dot:nth-child(2) {
92	    animation-delay: 600ms;
93	  }
94	
95	  .tv-dot:nth-child(3) {
96	    animation-delay: 1200ms;
97	  }
98	}
99	
100	/* §8.1.3/§8.1.4 — transições de barra e de estado RAG valem mesmo com
101	   reduced-motion? Não: §8.1.7 manda trocar seco. As classes utilitárias de
102	   transição são aplicadas via Tailwind nos componentes; aqui apenas as
103	   desligamos sob reduced-motion. */
104	@media (prefers-reduced-motion: reduce) {
105	  .tv-pixel-shift,
106	  .tv-fade-in,
107	  .tv-content-enter,
108	  .tv-dot {
109	    animation: none;
110	  }
111	}
