1	/**
2	 * @module use-mobile
3	 *
4	 * Hooks de detecção de dispositivo orientation-aware.
5	 *
6	 * Modos suportados:
7	 * - `mobile`  → viewport &lt; 768px **OU** 768-1279px em portrait
8	 *               (tablets em retrato seguem layout mobile por escolha de produto)
9	 * - `tablet`  → viewport 768-1279px **em landscape** (iPad, Surface deitado)
10	 * - `desktop` → viewport ≥ 1280px (qualquer orientação)
11	 */
12	
13	import * as React from 'react';
14	import { wideWarn } from '@/shared/lib/telemetry/wide-events';
15	
16	/** Viewport máximo (exclusivo) considerado mobile sem condicionar orientação. */
17	const MOBILE_BREAKPOINT = 768;
18	/** Viewport máximo (exclusivo) da faixa tablet; daí em diante é desktop. */
19	const TABLET_BREAKPOINT = 1280;
20	
21	export type DeviceMode = 'mobile' | 'tablet' | 'desktop';
22	
23	/**
24	 * Lê o modo atual usando `matchMedia.matches` em vez de `window.innerWidth/Height`.
25	 *
26	 * Motivo: durante `orientationchange` no iOS, `window.innerWidth/Height` pode
27	 * ainda refletir a orientação anterior por ~100ms. `matchMedia.matches` é
28	 * gerenciado pelo browser e sempre retorna o estado atual das media queries,
29	 * portanto é confiável imediatamente.
30	 */
31	function readDeviceMode(): DeviceMode {
32	  if (typeof window === 'undefined') return 'desktop';
33	  if (
34	    window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches
35	  ) {
36	    return 'mobile';
37	  }
38	  if (
39	    window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`).matches
40	  ) {
41	    return 'desktop';
42	  }
43	  // 768 ≤ width < 1280: orientação decide.
44	  return window.matchMedia('(orientation: landscape)').matches
45	    ? 'tablet'
46	    : 'mobile';
47	}
48	
49	/**
50	 * Retorna o modo de dispositivo atual: `mobile`, `tablet` ou `desktop`.
51	 * Reage a mudanças de viewport e orientação.
52	 */
53	export function useDeviceMode(): DeviceMode {
54	  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());
55	
56	  React.useLayoutEffect(() => {
57	    let timeoutId: ReturnType<typeof setTimeout> | undefined;
58	
59	    const update = () => {
60	      setMode(readDeviceMode());
61	      // No iOS, durante rotação física, o viewport "settles" alguns frames
62	      // depois do evento. Re-checa após 250ms pra garantir sincronização.
63	      if (timeoutId) clearTimeout(timeoutId);
64	      timeoutId = setTimeout(() => setMode(readDeviceMode()), 250);
65	    };
66	
67	    update();
68	
69	    const queries = [
70	      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
71	      window.matchMedia(
72	        `(min-width: ${MOBILE_BREAKPOINT}px) and (max-width: ${TABLET_BREAKPOINT - 1}px)`,
73	      ),
74	      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
75	      window.matchMedia('(orientation: landscape)'),
76	      window.matchMedia('(orientation: portrait)'),
77	    ];
78	    queries.forEach((mq) => mq.addEventListener('change', update));
79	    window.addEventListener('resize', update);
80	    window.addEventListener('orientationchange', update);
81	
82	    return () => {
83	      if (timeoutId) clearTimeout(timeoutId);
84	      queries.forEach((mq) => mq.removeEventListener('change', update));
85	      window.removeEventListener('resize', update);
86	      window.removeEventListener('orientationchange', update);
87	    };
88	  }, []);
89	
90	  return mode;
91	}
92	
93	/**
94	 * `true` quando o dispositivo deve usar layout mobile-essence.
95	 *
96	 * Filosofia: "essência mobile continua + adapta layout pra landscape". Por isso
97	 * inclui qualquer viewport não-desktop:
98	 *  - phones (&lt; 768px)
99	 *  - tablets em portrait (768-1279px, altura ≥ largura)
100	 *  - **tablets em landscape** (768-1279px, largura > altura) — neste caso o
101	 *    JSX mobile é renderizado, mas com classes `tablet:` do Tailwind aplicadas
102	 *    para re-arranjar o layout para landscape (grids mais largos, side panels,
103	 *    typography maior). Use {@link useIsTablet} para diferenciar.
104	 *
105	 * Equivale a `useDeviceMode() !== 'desktop'`.
106	 */
107	export function useIsMobile(): boolean {
108	  return useDeviceMode() !== 'desktop';
109	}
110	
111	/**
112	 * `true` quando o dispositivo está na faixa tablet **em landscape**
113	 * (768-1279px e largura > altura).
114	 */
115	export function useIsTablet(): boolean {
116	  return useDeviceMode() === 'tablet';
117	}
118	
119	/**
120	 * Detecta se o dispositivo possui câmera disponível.
121	 *
122	 * Em dispositivos mobile, assume presença de câmera por compatibilidade.
123	 * Em desktop, enumera os media devices para verificar.
124	 */
125	export function useHasCamera(): { hasCamera: boolean; isChecking: boolean } {
126	  const [hasCamera, setHasCamera] = React.useState(false);
127	  const [isChecking, setIsChecking] = React.useState(true);
128	
129	  React.useEffect(() => {
130	    const checkCamera = async () => {
131	      try {
132	        const userAgent = navigator.userAgent.toLowerCase();
133	        const isMobileDevice =
134	          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);
135	
136	        if (isMobileDevice) {
137	          setHasCamera(true);
138	          setIsChecking(false);
139	          return;
140	        }
141	
142	        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
143	          setHasCamera(false);
144	          setIsChecking(false);
145	          return;
146	        }
147	
148	        const devices = await navigator.mediaDevices.enumerateDevices();
149	        const videoDevices = devices.filter(
150	          (device) => device.kind === 'videoinput',
151	        );
152	        setHasCamera(videoDevices.length > 0);
153	      } catch (error) {
154	        wideWarn('device.camera_check_error', 'Erro ao verificar câmera', {
155	          attributes: {
156	            'error.message': error instanceof Error ? error.message : String(error),
157	            'device.has_media_devices': !!navigator.mediaDevices,
158	          },
159	        });
160	        const userAgent = navigator.userAgent.toLowerCase();
161	        const isMobileDevice =
162	          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);
163	        setHasCamera(isMobileDevice);
164	      } finally {
165	        setIsChecking(false);
166	      }
167	    };
168	
169	    checkCamera();
170	  }, []);
171	
172	  return { hasCamera, isChecking };
173	}
