              )
            ) : (
              <span className="text-[#7C887E]">sem meta cadastrada</span>
            )}
          </p>
        </div>

        {/* Mini-stats */}
        <div className="mt-auto grid grid-cols-3 gap-2 pt-3 sm:gap-4">
