                  <div
                    className="h-full rounded-full bg-gradient-to-r from-[#57715B] to-[#4a6250] transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none"
                    style={{ width: `${max > 0 ? Math.max(2, (p.quantidade / max) * 100) : 0}%` }}
                    data-testid="tv-top-product-bar"
                  />
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

