                    {p.nome}
                  </span>
                  <span className="shrink-0 font-momma text-[clamp(0.875rem,1.25vw,2.25rem)] font-medium leading-none text-[#2D362E] tabular-nums">
                    {formatInt(p.quantidade)}
                  </span>
                </div>
                <div className="mt-0.5 h-1.5 w-full rounded-full bg-[#57715B]/10 lg:h-2">
